/**
 * Shared atlas helpers for /system/ and /system/<cluster>/.
 *
 * Data: src/data/atlas.json (committed, generated by scripts/atlas-build.mjs on
 * the machine that owns the scheduler, then reviewed before it ships).
 */
import atlas from "../data/atlas.json";

export const { hero, patterns, bands, stats, loops, clusters, ground, shapes_page: shapesPage } = atlas as any;

export const running = loops.filter((l: any) => l.state === "running");
export const oneshots = loops.filter((l: any) => l.state !== "running");

export const tiles = clusters
  .filter((c: any) => c.kind !== "frame")
  .slice()
  .sort((a: any, b: any) => a.order - b.order);

export const frameBefore = clusters.find((c: any) => c.kind === "frame" && c.slot === "before");
export const frameAfter = clusters.find((c: any) => c.kind === "frame" && c.slot === "after");

/** Every cluster in reading order — the map's frames included. */
export const sections = clusters.slice().sort((a: any, b: any) => a.order - b.order);

export const clusterById = (id: string) => clusters.find((c: any) => c.id === id);

export const patternName = (id: string) => patterns.find((p: any) => p.id === id)?.name ?? "—";

export const countFor = (id: string) =>
  id === "rhythms" ? running.length : (clusterById(id)?.items?.length ?? 0);

export const unitFor = (id: string) =>
  id === "rhythms" ? "loops" : id === "crew" ? "seats" : id === "floor" ? "parts" : "entries";

export const groundCount = ground.stack.length + ground.fleet.length;

export const stamp = new Date(stats.generated_at).toLocaleDateString("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "America/Los_Angeles",
});
